INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (4, 0.0, 4, "2030/12/17 14:59:59", 24015, "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", "2019/07/31 12:00:00", 0.0, "カオリ（サマー）", 24, 1, 110501, 10021, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (4, 0.0, 1, "2030/12/17 14:59:59", 24016, "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", "2019/07/31 12:00:00", 0.0, "カオリ（サマー）", 24, 2, 110501, 10021, 4.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (4, 0.0, 4, "2030/12/17 14:59:59", 24017, "マジムンだらけで目が回るさ～！\nふらふらさ～！", "2019/07/31 12:00:00", 0.0, "カオリ（サマー）", 24, 3, 110501, 10021, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (1, 0.0, 2, "2030/12/17 14:59:59", 24018, "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", "2019/07/31 12:00:00", 0.0, "カオリ（サマー）", 24, 4, 110501, 10021, 5.2);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (5, 0.0, 6, "2030/12/17 14:59:59", 24019, "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", "2019/07/31 12:00:00", 0.0, "カオリ（サマー）", 24, 5, 110501, 10021, 4.2);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (2, 0.0, 2, "2030/12/17 14:59:59", 24020, "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", "2019/07/31 12:00:00", 0.0, "カオリ（サマー）", 24, 6, 110501, 10021, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (1, 0.0, 6, "2030/12/17 14:59:59", 24021, "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", "2019/07/31 12:00:00", 0.0, "カオリ（サマー）", 24, 7, 110501, 10021, 6.4);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (2, 0.0, 2, "2030/12/17 14:59:59", 24022, "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", "2019/07/31 12:00:00", 0.0, "カオリ（サマー）", 24, 8, 110501, 10021, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (6, 0.0, 3, "2030/12/17 14:59:59", 24023, "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", "2019/07/31 12:00:00", 0.0, "カオリ（サマー）", 24, 9, 110501, 10021, 10.08);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (1, 0.0, 2, "2030/12/17 14:59:59", 24024, "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", "2019/07/31 12:00:00", 0.0, "カオリ（サマー）", 24, 10, 110501, 10021, 5.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (2, 0.0, 2, "2030/12/17 14:59:59", 24025, "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", "2019/07/31 12:00:00", 0.0, "カオリ（サマー）", 24, 11, 110501, 10021, 0.0);
